import { bundleBrowserModule } from "../../../shared/browser-module-bundler.js";
export function bundleDevFile(absPath, ctx, dependencySnapshot, dependencyPinningSource, moduleServerOrigin) {
    return bundleBrowserModule(absPath, {
        adapter: ctx.adapter,
        projectDir: ctx.projectDir,
        config: ctx.config,
        projectId: ctx.projectId,
        projectSlug: ctx.projectSlug,
        moduleServerOrigin,
        dependencyPinningCacheKey: dependencySnapshot?.cacheKey,
        dependencyPinningDependencies: dependencySnapshot?.dependencies,
        dependencyPinningConfiguredVersions: dependencySnapshot?.configuredVersions,
        dependencyPinningSource,
    });
}
